const CACHE_NAME="gys-cache-v86",APP_VERSION="3.8.32";self.addEventListener("install",t=>{self.skipWaiting()}),self.addEventListener("activate",t=>{t.waitUntil(caches.keys().then(s=>Promise.all(s.map(h=>{if(h!==CACHE_NAME)return caches.delete(h)}))).then(()=>self.clients.claim()).then(()=>self.clients.matchAll({includeUncontrolled:!0}).then(s=>{s.forEach(h=>{try{h.postMessage({type:"SW_ACTIVATED",version:APP_VERSION})}catch{}})})))}),self.addEventListener("message",t=>{if(t.data&&t.data.type==="PURGE_URLS"){const s=Array.isArray(t.data.urls)?t.data.urls:[];caches.keys().then(h=>Promise.all(h.map(c=>caches.open(c).then(e=>e.keys().then(r=>Promise.all(r.map(i=>{const a=i.url||"";return s.some(u=>a.indexOf(u)!==-1)?e.delete(i):Promise.resolve(!1)}))))))).then(()=>{if(t.ports&&t.ports[0])try{t.ports[0].postMessage({type:"PURGED"})}catch{}if(t.source)try{t.source.postMessage({type:"PURGED"})}catch{}})}if(t.data&&t.data.type==="GET_VERSION"){if(t.ports&&t.ports[0])try{t.ports[0].postMessage({type:"VERSION",version:APP_VERSION})}catch{}if(t.source)try{t.source.postMessage({type:"VERSION",version:APP_VERSION})}catch{}}t.data&&t.data.type==="CLEAR_CACHE"&&caches.keys().then(s=>Promise.all(s.map(h=>caches.delete(h)))).then(()=>{if(t.ports&&t.ports[0])try{t.ports[0].postMessage({type:"CACHE_CLEARED"})}catch{}if(t.source)try{t.source.postMessage({type:"CACHE_CLEARED"})}catch{}})}),self.addEventListener("fetch",t=>{if(t.request.method==="GET"){var s;try{s=new URL(t.request.url)}catch{return}if(s.pathname.includes("/midi/")||s.pathname.includes("/pdf/")||s.pathname.includes("/chord/")||s.pathname.includes("assets-list.json")||s.pathname.includes("assets-lyrics.json")||s.pathname.includes("assets-chord-list.json")||s.pathname.endsWith(".sf2")||s.pathname.endsWith(".sf3")){t.respondWith(fetch(t.request));return}var h=s.origin===self.location.origin&&(s.pathname.endsWith(".js")||s.pathname.endsWith(".css")||s.pathname.endsWith(".html")||s.pathname==="/"||s.pathname.endsWith("/"));if(h){if(/[?&]v=/.test(s.search)){t.respondWith(caches.open(CACHE_NAME).then(e=>e.match(t.request).then(r=>{var i=fetch(t.request).then(a=>(a&&a.status===200&&e.put(t.request,a.clone()),a)).catch(()=>null);return r||i.then(a=>a||Response.error())})));return}t.respondWith(caches.open(CACHE_NAME).then(e=>fetch(t.request).then(r=>(r&&r.status===200&&e.put(t.request,r.clone()),r)).catch(()=>caches.match(t.request).then(r=>r||Response.error()))));return}var c=s.origin!==self.location.origin&&(s.pathname.endsWith(".js")||s.pathname.endsWith(".mjs"));if(c){t.respondWith(caches.open(CACHE_NAME).then(e=>e.match(t.request).then(r=>{var i=fetch(t.request).then(a=>(a&&(a.status===200||a.type==="opaque")&&e.put(t.request,a.clone()),a)).catch(()=>null);return r||i.then(a=>a||Response.error())})));return}t.respondWith(caches.match(t.request).then(e=>e||fetch(t.request).then(r=>{if(r&&(r.status===200||r.type==="opaque")){var i=r.clone();caches.open(CACHE_NAME).then(a=>{a.put(t.request,i)})}return r}).catch(()=>Response.error())))}});
